The profile handler after the passwordHash leak was "fixed":

// users/users.controller.ts
@Get(":id/profile")
async getProfile(@Param("id") id: string) {
  const user = await this.users.findById(id);   // the full users row as an entity
  delete user.passwordHash;
  return user;
}

// users.controller.spec.ts
it("does not return the password hash", async () => {
  const res = await controller.getProfile("u_1");
  expect(res).not.toHaveProperty("passwordHash");
});

